70.95,"note":"","text":"鍵？","start":2069.72,"favorite":false,"stableId":"ca87afe9-27d7-4f2c-b118-c7a610ad6d1f","sequenceId":463},{"id":464,"end":2076.29,"note":"","text":"私の… 正面の棚です","start":2071.05,"favorite":false,"stableId":"5cdee610-005a-4468-9045-cb9f592212cd","sequenceId":464},{"id":465,"end":2079.67,"note":"","text":"その後ろに…","start":2077.1,"favorite":false,"stableId":"b412ac83-346b-4f40-8167-8a15bd6d4930","sequenceId":465},{"id":466,"end":2082.96,"note":"","text":"鍵が…","start":2080.85,"favorite":false,"stableId":"72c7b6b3-d671-4acc-b624-e7c1e397f324","sequenceId":466},{"id":467,"end":2089.64,"note":"","text":"(ぶつかる音) (こずえたち) ヒッ…","start":2087.74,"favorite":false,"stableId":"f5b8263a-ed28-4b53-9bd2-92deb48e6c36","sequenceId":467},{"id":468,"end":2094.39,"note":"","text":"よし　明かりをつけよう","start":2090.91,"favorite":false,"stableId":"59076de2-c6e0-4fe4-b705-eba26711070f","sequenceId":468},{"id":469,"end":2101.32,"note":"","text":"(明かりのつく音)","start":2098.87,"favorite":false,"stableId":"2040571b-6091-4c95-960f-cb52a3a614d1","sequenceId":469},{"id":470,"end":2109.03,"note":"","text":"(小早川) 大丈夫ですか？","start":2107.26,"favorite":false,"stableId":"ecc5595a-b318-4b7b-bf1c-df072ae34b1a","sequenceId":470},{"id":471,"end":2113.29,"note":"","text":"光明寺さん？","start":2111.43,"favorite":false,"stableId":"959b768a-9bc0-4928-856c-075e6d35437d","sequenceId":471},{"id":472,"end":2120.59,"note":"","text":"(美琴) アア…","start":2118.48,"favorite":false,"stableId":"34a8e36e-970a-445e-beb8-3bda89023150","sequenceId":472},{"id":473,"end":2125.76,"note":"","text":"霊は？","start":2123.61,"favorite":false,"stableId":"65b96304-26e2-4007-8f3a-422d2155ee5e","sequenceId":473},{"id":474,"end":2129.18,"note":"","text":"現れましたか？","start":2126.44,"favorite":false,"stableId":"6666e693-1054-4059-9c9d-388d7c5eb40a","sequenceId":474},{"id":475,"end":2131.87,"note":"","text":"(小早川) 現れました","start":2130.07,"favorite":false,"stableId":"10c8cb95-7830-4d4b-bd9e-69905a3ab0b4","sequenceId":475},{"id":476,"end":2134.89,"note":"","text":"私の質問にも ちゃんと答えてくれました","start":2131.92,"favorite":false,"stableId":"8b4eb8d6-f8cc-4d5f-a248-086f5d350c0f","sequenceId":476},{"id":477,"end":2139.23,"note":"","text":"そうですか","start":2137.12,"favorite":false,"stableId":"3c004a01-1389-425d-a469-77d5ea426961","sequenceId":477},{"id":478,"end":2142.57,"note":"","text":"最後の言葉を覚えていますか？","start":2140.41,"favorite":false,"stableId":"0500ca90-72b0-4e1f-9d07-0f477820b176","sequenceId":478},{"id":479,"end":2145.26,"note":"","text":"霊ではなく――","start":2143.54,"favorite":false,"stableId":"dd20afb1-7359-45d6-a5d4-daea9741dbca","sequenceId":479},{"id":480,"end":2148.07,"note":"","text":"あなたが言ったように 聞こえたのですが","start":2145.31,"favorite":false,"stableId":"41eab13a-40be-488c-8ab4-19962a3c7310","sequenceId":480},{"id":481,"end":2155.08,"note":"","text":"(江南) ンッ…","start":2153.47,"favorite":false,"stableId":"82b95152-2153-4b0e-a0c5-7392b376deec","sequenceId":481},{"id":482,"end":2158.17,"note":"","text":"あっ…","start":2156.6,"favorite":false,"stableId":"9019983d-4d0f-4c50-989f-aa4c6b207a82","sequenceId":482},{"id":483,"end":2163.71,"note":"","text":"(小早川) ありましたよ","start":2161.77,"favorite":false,"stableId":"60b10839-4d28-4eab-9950-d883c3ddb05e","sequenceId":483},{"id":484,"end":2168.59,"note":"","text":"あの鍵に どんな意味があるんですか？","start":2165.06,"favorite":false,"stableId":"bdcd401f-7e8b-4eae-9ce6-8cd1e8c4e098","sequenceId":484},{"id":485,"end":2171.47,"note":"","text":"(美琴) 分かりません","start":2169.23,"favorite":false,"stableId":"b23f2e5e-56bc-4dcf-86cb-8c2c3923a774","sequenceId":485},{"id":486,"end":2174.31,"note":"","text":"とりあえず…","start":2172.45,"favorite":false,"stableId":"08af5249-a75b-4963-ac33-62eb21ed0c89","sequenceId":486},{"id":487,"end":2181.27,"note":"","text":"この鍵を通して 何か見えてくるかもしれませんので――","start":2175.24,"favorite":false,"stableId":"b06f3818-4893-4222-a89b-b8f055a8dc72","sequenceId":487},{"id":488,"end":2187.03,"note":"","text":"私が預かっておくのが いいかと思います","start":2182.92,"favorite":false,"stableId":"366df15e-bbaa-490d-9e15-cfa7fda7a0e0","sequenceId":488},{"id":489,"end":2193.7,"note":"","text":"(時鐘音)","start":2191.05,"favorite":false,"stableId":"cc6877e4-1934-46b4-bce2-35ad7a42bb4f","sequenceId":489},{"id":490,"end":2197.27,"note":"","text":"(こずえ) すごかったですよね","start":2194.18,"favorite":false,"stableId":"9da2b846-b424-4bea-a366-b0a5fd94b313","sequenceId":490},{"id":491,"end":2199.06,"note":"","text":"(渡辺) 確かに びっくりしました","start":2197.32,"favorite":false,"stableId":"e8cc9d71-fc23-40bb-bc9a-c3460f57ec44","sequenceId":491},{"id":492,"end":2202.88,"note":"","text":"この前 テレビで見たときよりも 断然 迫力あったし","start":2199.11,"favorite":false,"stableId":"c5f4aa4f-9048-4100-b528-c6c804d6ee96","sequenceId":492},{"id":493,"end":2206.55,"note":"","text":"(瓜生) 江南さんは？ どう思いました？","start":2202.98,"favorite":false,"stableId":"ea13da45-2414-4ad4-9973-fe3044892508","sequenceId":493},{"id":494,"end":2208.74,"note":"","text":"(江南) そうだね","start":2206.77,"favorite":false,"stableId":"c88749a4-b9e9-4b2f-836c-28b795dbe6c3","sequenceId":494},{"id":495,"end":2210.26,"note":"","text":"(シャッター音)","start":2208.79,"favorite":false,"stableId":"7eccd40e-b843-4b61-98d1-b6f801eb3de5","sequenceId":495},{"id":496,"end":2214.41,"note":"","text":"(江南) 僕は｢CHAOS｣の編集部には 入ったばかりで――","start":2210.57,"favorite":false,"stableId":"03e5c068-b362-465d-9ee6-f4378bbc3e5d","sequenceId":496},{"id":497,"end":2217.6,"note":"","text":"今回みたいな取材は 初めてだったから――","start":2214.46,"favorite":false,"stableId":"966443e2-498a-4d16-b713-ec9d44c1def8","sequenceId":497},{"id":498,"end":2220.23,"note":"","text":"やっぱり驚いたな","start":2217.83,"favorite":false,"stableId":"ac3fee9d-2d19-410d-bd02-16268b9a1161","sequenceId":498},{"id":499,"end":2225.07,"note":"","text":"(瓜生) ふ～ん　そうですか","start":2221.62,"favorite":false,"stableId":"bca602cc-ba49-4bdb-bce9-490a51f47d0b","sequenceId":499},{"id":500,"end":2228.47,"note":"","text":"(早紀子) どうしたの？ 瓜生くん","start":2226.67,"favorite":false,"stableId":"b85342a9-cb22-43bf-8e47-53d0e7942e91","sequenceId":500},{"id":501,"end":2230.51,"note":"","text":"なんだか不満そうだけど","start":2228.52,"favorite":false,"stableId":"715f265e-1bcc-4b98-bb31-f11f48258e20","sequenceId":501},{"id":502,"end":2233.47,"note":"","text":"(こずえ) あれ～？ 瓜生さん 疑ってるんですか？","start":2230.56,"favorite":false,"stableId":"b7e2440a-8413-4036-91bb-4abc4b686c9a","sequenceId":502},{"id":503,"end":2235.27,"note":"","text":"いっつも そうなんだから","start":2233.52,"favorite":false,"stableId":"23edd9c0-5c09-4bd7-a66d-2ea3c8086ddf","sequenceId":503},{"id":504,"end":2237.83,"note":"","text":"(河原崎) いやいや こずえちゃん","start":2235.32,"favorite":false,"stableId":"e4d747b2-1ee7-4b52-962a-83a7923bd3e6","sequenceId":504},{"id":505,"end":2240,"note":"","text":"ンッ…","start":2238.55,"favorite":false,"stableId":"81d0523f-acee-4c0c-9a25-0845dbb8be31","sequenceId":505},{"id":506,"end":2243.15,"note":"","text":"俺も民佐男と同じだな","start":2240.39,"favorite":false,"stableId":"7993c1c9-f594-47f4-8c08-938adfd60bf5","sequenceId":506},{"id":507,"end":2246.34,"note":"","text":"どうも気に食わないんだよな","start":2243.2,"favorite":false,"stableId":"8efaab51-56d0-45e9-bea7-32e173439324","sequenceId":507},{"id":508,"end":2251.24,"note":"","text":"(渡辺) まさか あれが全部 インチキだったっていうんですか？","start":2246.85,"favorite":false,"stableId":"b5bcebbc-dd5d-4709-8744-2fa99321dd84","sequenceId":508},{"id":509,"end":2254.72,"note":"","text":"(こずえ) そんな… せっかく感動してたのに","start":2251.29,"favorite":false,"stableId":"b84f9a93-5772-4bd1-be2d-b169489795e5","sequenceId":509},{"id":510,"end":2258.5,"note":"","text":"(瓜生) 交霊会の真偽は さておくとして――","start":2255.4,"favorite":false,"stableId":"3c326b5d-beac-4e9f-8deb-952ea3d729e1","sequenceId":510},{"id":511,"end":2261,"note":"","text":"気になるのは 光明寺さん","start":2258.55,"favorite":false,"stableId":"e5a503cf-988f-4c42-81be-2758d5b04fd7","sequenceId":511},{"id":512,"end":2265.21,"note":"","text":"…に乗り移った霊が 話した内容なんですけど","start":2261.05,"favorite":false,"stableId":"d93d26b8-156d-42bb-ba0b-4f034c6a72c1","sequenceId":512},{"id":513,"end":2266.73,"note":"","text":"(江南) 内容って？","start":2265.26,"favorite":false,"stableId":"48662498-8756-4d88-b591-7ae42a7c9000","sequenceId":513},{"id":514,"end":2271.26,"note":"","text":"(瓜生) 自分は“とわ”という 名前だと言ってましたよね","start":2267.12,"favorite":false,"stableId":"a6c8d164-f106-4734-80c2-9364612a9773","sequenceId":514},{"id":515,"end":2274.89,"note":"","text":"古峨倫典氏の娘は 本当に そんな名前だったんですか？","start":2271.31,"favorite":false,"stableId":"1089fe24-7e96-400b-9e94-b36a715171d1","sequenceId":515},{"id":516,"end":2278.95,"note":"","text":"うん　“永遠”という字を書いて","start":2274.94,"favorite":false,"stableId":"83ec7f2f-dfee-4eef-9bd3-d5babb3b63e5","sequenceId":516},{"id":517,"end":2282.61,"note":"","text":"確か 倫典氏よりも前に亡くなったって――","start":2279,"favorite":false,"stableId":"458ed537-90b0-4db0-bd5e-59eaa9addff4","sequenceId":517},{"id":518,"end":2284.52,"note":"","text":"小早川さんから聞いたし――","start":2282.66,"favorite":false,"stableId":"adb87aeb-6488-41e8-b99c-8481f543c8e2","sequenceId":518},{"id":519,"end":2287.03,"note":"","text":"管理人の伊波さんの話では…","start":2284.57,"favorite":false,"stableId":"28a979ad-0c73-46d2-8146-bf2c58207233","sequenceId":519},{"id":520,"end":2291.11,"note":"","text":"あの部屋は お嬢さまのお部屋です","start":2287.08,"favorite":false,"stableId":"8e4a5473-9243-481f-80f6-d62aa1a02e14","sequenceId":520},{"id":521,"end":2293.74,"note":"","text":"(伊波) 10年前に亡くなった――","start":2291.16,"favorite":false,"stableId":"049be9c9-abb1-4cb6-a01b-a51e3226c423","sequenceId":521},{"id":522,"end":2295.68,"note":"","text":"お嬢さまの","start":2293.79,"favorite":false,"stableId":"a42ddb1c-7dad-4e3f-9408' WHERE "id" = '9ca51cd4-28eb-4034-ac60-51fd60f0f625' AND changes() = 1;

UPDATE "materials" SET "content_payload" = "content_payload" || '-7ae8e8bb8fc4","sequenceId":522},{"id":523,"end":2299.64,"note":"","text":"10年前か…","start":2296.36,"favorite":false,"stableId":"4080fd46-0aab-4c73-978f-04110bd5a3b1","sequenceId":523},{"id":524,"end":2301.75,"note":"","text":"小早川さんの質問には――","start":2300.07,"favorite":false,"stableId":"893fe1ad-5e59-47d4-97f1-116e8f4cfba1","sequenceId":524},{"id":525,"end":2305.1,"note":"","text":"死因は 病死でも事故でもないって 答えてましたよね","start":2301.8,"favorite":false,"stableId":"f4e76845-ba89-4a73-9081-459f279cf59d","sequenceId":525},{"id":526,"end":2309.09,"note":"","text":"自殺か あるいは…","start":2305.58,"favorite":false,"stableId":"c2bca0f9-3cd7-45b4-ba24-a406ae30cd1c","sequenceId":526},{"id":527,"end":2312.94,"note":"","text":"(美琴) 真っ暗…","start":2309.14,"favorite":false,"stableId":"1ef994cd-ef64-4457-954b-a26632e7e5af","sequenceId":527},{"id":528,"end":2314.32,"note":"","text":"穴…","start":2313,"favorite":false,"stableId":"6c835d9a-f47f-4fd1-b077-6e1a1bbce382","sequenceId":528},{"id":529,"end":2318.45,"note":"","text":"痛い… 痛い…","start":2315.09,"favorite":false,"stableId":"280722f7-260d-44e8-b206-6e1fa9dbc239","sequenceId":529},{"id":530,"end":2323.12,"note":"","text":"(早紀子) まさか あの子が自殺したなんて…","start":2318.76,"favorite":false,"stableId":"ae916174-64fa-4a6f-bf25-a3a345d2cd56","sequenceId":530},{"id":531,"end":2326.19,"note":"","text":"(江南)“あの子”って…","start":2324.51,"favorite":false,"stableId":"f22a2cdb-e1af-4b28-91ea-c7e4d0526dbd","sequenceId":531},{"id":532,"end":2328.74,"note":"","text":"樫さんは その子を知ってるんですか？","start":2326.24,"favorite":false,"stableId":"9fe82129-f58d-4fb1-b694-cf9ec7f5fc12","sequenceId":532},{"id":533,"end":2330.65,"note":"","text":"(渡辺) そういえば――","start":2328.79,"favorite":false,"stableId":"1b2c1aa5-6388-4265-98c6-ed281c48823a","sequenceId":533},{"id":534,"end":2335.41,"note":"","text":"先輩たち 10年前に この近くに 合宿に来たとか言ってましたよね","start":2330.7,"favorite":false,"stableId":"9f5929cc-4789-41cc-8db3-00fd8ba27a4c","sequenceId":534},{"id":535,"end":2336.83,"note":"","text":"ええ","start":2335.46,"favorite":false,"stableId":"2c23a539-7daf-4ff7-b3ee-b32a220d2b11","sequenceId":535},{"id":536,"end":2342.81,"note":"","text":"多分 合宿のとき 森で遊んでいて そこで","start":2336.88,"favorite":false,"stableId":"70cf828e-983d-4a02-ac67-518f4d5c10a9","sequenceId":536},{"id":537,"end":2347.85,"note":"","text":"(河原崎) 俺は よく覚えてないんだけど","start":2343.74,"favorite":false,"stableId":"77aa6d1f-5c2a-4cb6-bf7c-cbe82cb8fbd0","sequenceId":537},{"id":538,"end":2351.26,"note":"","text":"僕も はっきりと覚えているわけじゃ…","start":2348.12,"favorite":false,"stableId":"4ee12182-104b-4fb9-9a9a-2adaa9d75a66","sequenceId":538},{"id":539,"end":2354.76,"note":"","text":"何しろ 10年前 小学校５年のときですから","start":2351.31,"favorite":false,"stableId":"6c84b5e8-70de-4881-bb96-d1488aafac87","sequenceId":539},{"id":540,"end":2357.81,"note":"","text":"(早紀子) 私が なんとなく覚えているの――","start":2354.81,"favorite":false,"stableId":"6ae469e3-9a49-44eb-9946-00ced662c450","sequenceId":540},{"id":541,"end":2363.7,"note":"","text":"森で女の子に会って その子と この家まで一緒に来て","start":2357.86,"favorite":false,"stableId":"3133d015-9cc3-4685-9ef5-3cedb165f66a","sequenceId":541},{"id":542,"end":2369.08,"note":"","text":"(早紀子) そこで あの男の子にも 会ったような気がして…","start":2363.93,"favorite":false,"stableId":"0327b421-a283-4323-9c78-951463f86d75","sequenceId":542},{"id":543,"end":2371.04,"note":"","text":"男の子…","start":2369.18,"favorite":false,"stableId":"14f1bd89-9fc2-4c61-8c38-ba7f85db150a","sequenceId":543},{"id":544,"end":2374.76,"note":"","text":"それが あの由季弥という少年だったと？","start":2371.44,"favorite":false,"stableId":"6a222b6a-717c-48ba-8263-41919fe74130","sequenceId":544},{"id":545,"end":2377.74,"note":"","text":"(早紀子) じゃないかと思うんですけど","start":2374.9,"favorite":false,"stableId":"976bc7af-847a-4431-bd63-a2330731695c","sequenceId":545},{"id":546,"end":2380.1,"note":"","text":"(瓜生) ねえ 江南さん","start":2377.79,"favorite":false,"stableId":"46089d75-110c-4baa-81a4-e1babe3b5494","sequenceId":546},{"id":547,"end":2383.97,"note":"","text":"あのとき彼が言っていた言葉 覚えているでしょう？","start":2380.2,"favorite":false,"stableId":"f5c076e7-bcfe-4141-b3f6-6fa33b22a5b1","sequenceId":547},{"id":548,"end":2387.14,"note":"","text":"姉さんを いじめに来たんじゃないだろうね？","start":2384.07,"favorite":false,"stableId":"74899ad8-b37e-414c-8c3a-d127ea978963","sequenceId":548},{"id":549,"end":2389.46,"note":"","text":"だったら 僕が やっつけてやる","start":2387.37,"favorite":false,"stableId":"c592d856-7812-4081-8651-5fb950349555","sequenceId":549},{"id":550,"end":2392.34,"note":"","text":"(瓜生) お姉さんが 永遠さんのことだとしたら――","start":2389.51,"favorite":false,"stableId":"7993f1e3-3232-4f38-8afe-7553e7afef2e","sequenceId":550},{"id":551,"end":2395.01,"note":"","text":"とっくに死んだはずの姉について――","start":2392.39,"favorite":false,"stableId":"c89d387e-65b2-4081-93a5-cc257d441e5e","sequenceId":551},{"id":552,"end":2397.64,"note":"","text":"まるで 生きているかのように語ってたし","start":2395.06,"favorite":false,"stableId":"c1c4fd7a-9aca-4298-ab7c-da9af9b9f49a","sequenceId":552},{"id":553,"end":2400.14,"note":"","text":"(渡辺) ひょっとして 由季弥くんには――","start":2397.69,"favorite":false,"stableId":"b891ff49-5fc7-4e59-a550-044cd46ca4fd","sequenceId":553},{"id":554,"end":2402.06,"note":"","text":"幽霊になったお姉さんが 見えるとか!?","start":2400.19,"favorite":false,"stableId":"d67ebb7d-b54b-4daa-880b-0b8467f9ecc1","sequenceId":554},{"id":555,"end":2404.94,"note":"","text":"(こずえ) そっか！ じゃあ 時計屋敷の亡霊の正体は――","start":2402.11,"favorite":false,"stableId":"98aa9eec-0e45-471e-8eac-8984706bff81","sequenceId":555},{"id":556,"end":2407.15,"note":"","text":"やっぱり 古峨永遠さんってこと？","start":2404.99,"favorite":false,"stableId":"8ab6d19f-1977-4593-95ad-8a424b709069","sequenceId":556},{"id":557,"end":2409.5,"note":"","text":"(内海) もう いいかげんにしてくれ！","start":2407.2,"favorite":false,"stableId":"88870bfa-5a9e-46f7-bca5-595b882c2828","sequenceId":557},{"id":558,"end":2412.28,"note":"","text":"そういうの 俺 苦手なんだから","start":2409.68,"favorite":false,"stableId":"0f9ebf4d-00df-4d63-82e9-008a214e9f62","sequenceId":558},{"id":559,"end":2414.09,"note":"","text":"(江南) あっ…","start":2412.33,"favorite":false,"stableId":"f0060261-f8c5-4138-a3c0-218ef206df8b","sequenceId":559},{"id":560,"end":2417.26,"note":"","text":"怖かったですか？","start":2414.56,"favorite":false,"stableId":"60d825f1-8259-48cf-9191-bb5c87f73ef5","sequenceId":560},{"id":561,"end":2421.34,"note":"","text":"(内海) このあと みんな １人で寝なきゃならないんだし","start":2417.36,"favorite":false,"stableId":"c203b006-67c9-4aea-9e9d-4ab72c63c75e","sequenceId":561},{"id":562,"end":2428.27,"note":"","text":"(小早川) なんだ まだ みんな起きてたんだ？","start":2424.2,"favorite":false,"stableId":"565cb5f2-dd9b-4ef4-bb2f-43438dcff9ac","sequenceId":562},{"id":563,"end":2432.4,"note":"","text":"あしたもあるし そろそろ お開きにしないか","start":2429.08,"favorite":false,"stableId":"e8dad6c9-5a72-47a1-8680-7662c6cc9736","sequenceId":563},{"id":564,"end":2436.36,"note":"","text":"そうですね","start":2434.21,"favorite":false,"stableId":"2fc892de-8c7d-4e74-9b9b-1ab5096603eb","sequenceId":564},{"id":565,"end":2437.43,"note":"","text":"解散！","start":2436.46,"favorite":false,"stableId":"c6054c7f-7a37-408a-b0e6-c9713cde38bc","sequenceId":565},{"id":566,"end":2438.43,"note":"","text":"(渡辺たち) はい","start":2437.48,"favorite":false,"stableId":"cbf100d5-4d14-4c9d-8457-a8be4dc5d0b2","sequenceId":566},{"id":567,"end":2440.57,"note":"","text":"(早紀子) では おやすみなさい","start":2438.48,"favorite":false,"stableId":"05f5e185-b1f7-4f77-b8a3-41110fe94669","sequenceId":567},{"id":568,"end":2443.95,"note":"","text":"(河原崎) おやすみなさい","start":2442.13,"favorite":false,"stableId":"1fca2289-6a31-467f-8bca-acfcb2bf6d02","sequenceId":568},{"id":569,"end":2458.13,"note":"","text":"アア… そっか","start":2454.9,"favorite":false,"stableId":"b32e371a-2cc3-4203-92c9-87bb1b3c303b","sequenceId":569},{"id":570,"end":2479.11,"note":"","text":"(時鐘音)","start":2473.16,"favorite":false,"stableId":"efd123d0-69c6-46ea-bc66-e117c9496189","sequenceId":570},{"id":571,"end":2492.79,"note":"","text":"(ドアの開く音)","start":2490.97,"favorite":false,"stableId":"b0ffd9db-a490-4c9f-99d6-9c807f3d55a6","sequenceId":571},{"id":572,"end":2501.93,"note":"","text":"(ドアの閉まる音)","start":2500.4,"favorite":false,"stableId":"619c7aff-58f8-4c31-a496-6dc56f0c017b","sequenceId":572},{"id":573,"end":2526.24,"note":"","text":"光明寺さんの部屋？","start":2523.42,"favorite":false,"stableId":"f33dc0f9-5973-414d-93b2-15158db5a6b8","sequenceId":573},{"id":574,"end":2570.74,"note":"","text":"(においを嗅ぐ音)","start":2568.93,"favorite":false,"stableId":"ba1aedc9-08cf-422f-ab09-33c6076b8c1f","sequenceId":574},{"id":575,"end":2577.04,"note":"","text":"(においを嗅ぐ音)","start":2575.52,"favorite":false,"stableId":"d73f9ac7-29ef-4f16-aec1-bcac7c3655a7","sequenceId":575},{"id":576,"end":2610.16,"note":"","text":"(女性の声) どうして… 何を…","start":2607.13,"favorite":false,"stableId":"64f49747-1d6d-46d4-aa2d-4c50fd6d0e9e","sequenceId":576},{"id":577,"end":2612.06,"note":"","text":"あなた…","start":2610.97,"favorite":false,"stableId":"475364dc-d5e0-49f1-9f47-d37cfa69eb4c","sequenceId":577},{"id":578,"end":2613.87,"note":"","text":"(何かが壊れるような音) (江南) ハッ…","start":2612.11,"favorite":false,"stableId":"a8cfcff6-92f5-4f9d-af07-fac96115cf05","sequenceId":578},{"id":579,"end":2620.54,"note":"","text":"(江南) 光明寺さん？","start":2618.6,"favorite":false,"stableId":"c43a53a5-4ec2-4ead-952b-ef84f7151bd1","sequenceId":579},{"id":580,"end":2622.9,"note":"","text":"光明寺さん！ 何が…","start":2621.48,"favorite":false,"stableId":"0772be86-3ede-4c7e-9ddd-b3ebd52b9dec","sequenceId":580},{"id":581,"end":2625.7,"note":"","text":"(時鐘音)","start":2622.95,"favorite":false,"stableId":"d28cdb47-b0f6-4c2b-a817-24d0f03e95fe","sequenceId":581},{"id":582,"end":2631.05,"note":"","text":"(時鐘音)","start":2625.75,"favorite":false,"stableId":"1f5c3da5-5bc1-4657-a84c-60fe5d05e778","sequenceId":582},{"id":583,"end":2640.55,"note":"","text":"(ドアノブを回す音)","start":2638.83,"favorite":false,"stableId":"cd2bc9d7-f8e1-4c42-b4ae-b05b1145532e","sequenceId":583},{"id":584,"end":2641.88,"note":"","text":"(江南) えっ？","start":2640.6,"favorite":false,"stableId":"d8a86e1a-f715-4db7-a430-3eca498e2dd8","sequenceId":584},{"id":585,"end":2643.57,"note":"","text":"(ドアを開けようとする音)","start":2641.93,"favorite":false,"stableId":"9d20eb9e-da2e-4c63-bf13-bdc46c0bc2e0","sequenceId":585},{"id":586,"end":2667.92,"note":"","text":"フフッ…","start":2666.31,"favorite":false,"stableId":"1b5eea0c-0438-4c78-9fc3-bcfd9b912a41","sequenceId":586},{"id":587,"end":2684.73,"note":"","text":"(足音)","start":2680.83,"favorite":false,"stableId":"832de076-20d3-4112-9edf-39c7721e26ba","sequenceId":587},{"id":588,"end":2689.78,"note":"","text":"(鹿谷) こんばんは どうも いきなり すいません","start":2685.25,"favorite":false,"stableId":"46c3e559-554b-4870-a35b-e29dc93f6ce9","sequenceId":588},{"id":589,"end":2693.87,"note":"","text":"(伊波) あの… どちらさまで？","start":2690.67,"favorite":false,"stableId":"547bad3a-bde7-47b5-8dfd-737399aaffb3","sequenceId":589},{"id":590,"end":2696.69,"note":"","text":"僕は鹿谷門実といいます","start":2693.97,"favorite":false,"stableId":"60208328-f041-43c4-91d1-ec9f3193ed42","sequenceId":590},{"id":591,"end":2698.73,"note":"","text":"稀譚社のコナンくん…","start":2696.74,"favorite":false,"stableId":"b709b5c0-e0e7-4242-8ad5-5f3a4fb79ba0","sequenceId":591},{"id":592,"end":2701.37,"note":"","text":"江南くんの友人でして","start":2698.78,"favorite":false,"stableId":"db2d59ba-e4b4-46dd-b183-3ea7b1e94052","sequenceId":592},{"id":593,"end":2704.36,"note":"","text":"(伊波) 確かに その方は いらっしゃいますが","start":2701.42,"favorite":false,"stableId":"e9bd742a-93d8-422f-b9d3-13fe9bd4aa89","sequenceId":593},{"id":594,"end":2706.55,"note":"","text":"(鹿谷) 今日のことは コナンくん…","start":2704.41,"favorite":false,"stableId":"475abcb3-472d-47fd-932e-4356a0c61c93","sequenceId":594},{"id":595,"end":2708.45,"note":"","text":"江南くんから聞いていまして","start":2706.65,"favorite":false,"stableId":"d77142fd-7267-4091-9512-c3710061df23","sequenceId":595},{"id":596,"end":2712.12,"note":"","text":"いや こちらのお屋敷を 一度 是非 この目で――","start":2708.5,"favorite":false,"stableId":"256288e4-2740-4d46-9a7a-cb77cd7f7c7f","sequenceId":596},{"id":597,"end":2714.89,"note":"","text":"じっくり見てみたいなと いうのがあったもので","start":2712.17,"favorite":false,"stableId":"f0b35789-6ebb-4105-ac72-aaa8bca0158c","sequenceId":597},{"id":598,"end":2719.5,"note":"","text":"あっ こちら 福西くん","start":2716.99,"favorite":false,"stableId":"7b38c234-0331-4f39-bc00-369780986376","sequenceId":598},{"id":599,"end":2722.63,"note":"","text":"彼もＷ大の学生の仲間なんですがね","start":2719.55,"favorite":false,"stableId":"2e1509de-34c5-4be2-b438-13192cd4296e","sequenceId":599},{"id":600,"end":2723.96,"note":"","text":"(伊波) 福西…","start":2722.68,"favorite":false,"stableId":"07ea4007-88bc-4f7b-8bad-671e5107e94f","sequenceId":600},{"id":601,"end":2728.23,"note":"","text":"(鹿谷) はい　何か事情があって 遅刻しちゃったようなんですよ","start":2724.01,"favorite":false,"stableId":"b7e58741-9c0e-44c6-b343-a7111ae27492","sequenceId":601},{"id":602,"end":2733.24,"note":"","text":"残念だったね","start":2731.5,"favorite":false,"stableId":"e3b4be91-b126-47bc-82ff-4b99f7d84ca1","sequenceId":602},{"id":603,"end":2738.65,"note":"","text":"これが時計館ですか","start":2734.8,"favorite":false,"stableId":"35d1ba6c-f7d3-4ad1-b966-e7c3a160ee8f","sequenceId":603},{"id":604,"end":2742.75,"note":"","text":"あ～ やっぱり 明るいうちに来るべきだったなぁ","start":2738.7,"favorite":false,"stableId":"092b67ca-cf28-4930-adab-432fbe23e2c7","sequenceId":604},{"id":605,"end":2747.32,"note":"","text":"こちらを設計したのは 建築家の中村青司でしたよね","start":2742.85,"favorite":false,"stableId":"38dcf838-06ce-41fe-97c7-82a8a690744e","sequenceId":605},{"id":606,"end":2751.84,"note":"","text":"僕は 実は 中村青司の研究家でしてね","start":2747.37,"favorite":false,"stableId":"70e2cb06-250e-46c5-b601-bfc2dacaaa98","sequenceId":606},{"id":607,"end":2753.16,"note":"","text":"研究家…","start":2751.98,"favorite":false,"stableId":"e29fdae3-dde6-4a02-97ea-27b47413d0fc","sequenceId":607},{"id":608,"end":2755.68,"note":"","text":"あっ そうだ","start":2753.21,"favorite":false,"stableId":"71d4c0d5-3796-4f89-becc-5e8c97febfe4","sequenceId":608},{"id":609,"end":2759.93,"note":"","text":"お近づきのしるしに こちらを差し上げます","start":2756.11,"favorite":false,"stableId":"ddb7a86a-3527-4ba4-a4a5-9cc82d7bb3f8","sequenceId":609},{"id":610,"end":2764.19,"note":"","text":"この手の小説がお嫌いでなければ 是非 読んでやってください","start":2760.03,"favorite":false,"stableId":"c940436c-f742-4a85-934e-ae4e23ecc1f7","sequenceId":610},{"id":611,"end":2789.17,"note":"","text":"針のない時計塔","start":2786.43,"favorite":false,"stableId":"b8ffae5a-560b-473d-a381-463effef2e39","sequenceId":611},{"id":612,"end":2802.54,"note":"","text":"(鹿谷) どうかしたのかい？","start":2801.24,"favorite":false,"stableId":"ad562ca4-f08d-4d33-a900-f82d84df6c8f","sequenceId":612},{"id":613,"end":2804.56,"note":"","text":"(虫の羽音) (福西) えっ？","start":2802.59,"favorite":false,"stableId":"167a26b8-a876-4370-bde0-a1e436f9603f","sequenceId":613},{"id":614,"end":2808.72,"note":"","text":"(テレビの音楽)","start":2805.83,"favorite":false,"stableId":"a0d3b847-9e56-4a57-a2f8-15f98fd1dd8d","sequenceId":614},{"id":615,"end":2811.01,"note":"","text":"(鹿谷) フフッ… それが つまり 問題の――","start":2808.77,"favorite":false,"stableId":"c8b7f59d-5ff4-49a2-a11e-f924405172f5","sequenceId":615},{"id":616,"end":2814.49,"note":"","text":"時計屋敷の亡霊だったんじゃ ないかって？","start":2811.06,"favorite":false,"stableId":"3fe8f88f-567a-4a97-bf17-5dd22152a542","sequenceId":616},{"id":617,"end":2818.22,"note":"","text":"確か ウワサでは 少女の亡霊だったはずだけども","start":2814.75,"favorite":false,"stableId":"88284dd3-5606-422e-9231-2cd14c2013a6","sequenceId":617},{"id":618,"end":2819.48,"note":"","text":"んっ…","start":2818.27,"favorite":false,"stableId":"88fd94f1-dc0b-45c6-9dfb-ec93840b2326","sequenceId":618},{"id":619,"end":2820.77,"note":"","text":"(福西) ありがとうございます","start":2819.53,"favorite":false,"stableId":"1d4ce302-05ce-49c1-b76e-1f7bd8c68dc3","sequenceId":619},{"id":620,"end":2822.66,"note":"","text":"(グラスを当てる音) (鹿谷)はい 乾杯","start":2820.82,"favorite":false,"stableId":"0ab3f19a-6d0e-4e4f-a10a-ca5f0f76ed69","sequenceId":620},{"id":621,"end":2829.38,"note":"","text":"あの屋敷については 僕も独自に調べてみたんだけどね","start":2825.35,"favorite":false,"stableId":"5469984d-8ce2-46d1-8e9f-43efbca3fd8f","sequenceId":621},{"id":622,"end":2832.45,"note":"","text":"(鹿谷) うちの２番目の兄が――","start":2830.94,"favorite":false,"stableId":"655e3fce-92b5-41d9-9ca9-689eb9fe857d","sequenceId":622},{"id":623,"end":2836.12,"note":"","text":"実は 大分県警捜査一課の 警部どのなんだよ","start":2832.5,"favorite":false,"stableId":"888e563d-70cf-450a-acb5-904d2d6f2213","sequenceId":623},{"id":624,"end":2838.04,"note":"","text":"たまたま こっちに出張だっていうから――","start":2836.17,"favorite":false,"stableId":"957ee1fd-0235-4b91-a547-8f8ed82168bf","sequenceId":624},{"id":625,"end":2840.76,"note":"","text":"神奈川県警の コネなんかも使ってね","start":2838.09,"favorite":false,"stableId":"094227ec-56e6-4cce-80fe-9fb53719946e","sequenceId":625},{"id":626,"end":2844.14,"note":"","text":"(島田 修) こっちは仕事で来てるんだからさ","start":2840.91,"favorite":false,"stableId":"4f41b215-1bf9-4586-8b78-ea9dbd9ede75","sequenceId":626},{"id":627,"end":2848.06,"note":"","text":"便利使いしないでもらいたいね","start":2845.03,"favorite":false,"stableId":"cfbcbddf-1026-4783-aecb-da53c10c25fa","sequenceId":627},{"id":628,"end":2851.02,"note":"","text":"(飲む音)","start":2848.12,"favorite":false,"stableId":"8816a3a9-cb04-4430-96a0-93253749d710","sequenceId":628},{"id":629,"end":2853.51,"note":"","text":"ハァ…","start":2852.08,"favorite":false,"stableId":"f9f9f2c7-63a9-4f60-9f39-5255b666db43","sequenceId":629},{"id":630,"end":2854.89,"note":"","text":"そもそも お前はな","start":2853.56,"favorite":false,"stableId":"57dfb72a-3bc4-4ab3-b4c8-6cd7af9fc224","sequenceId":630},{"id":631,"end":2857.26,"note":"","text":"説教はいいから","start":2854.94,"favorite":false,"stableId":"e47f40db-5559-456d-9419-f1097ed7d93c","sequenceId":631},{"id":632,"end":2860.74,"note":"","text":"うん？ 何か分かったのかな？","start":2857.31,"favorite":false,"stableId":"b07ab1a8-fb6a-436b-a8fb-4863ea6ae134","sequenceId":632},{"id":633,"end":2866.37,"note":"","text":"古峨精計社の前会長 古峨倫典の関係者で――","start":2861.3,"favorite":false,"stableId":"e8c9a790-3b63-4c63-b303-b1c1c297c507","sequenceId":633},{"id":634,"end":2869.94,"note":"","text":"この10年間で亡くなったのは７人","start":2866.6,"favorite":false,"stableId":"16da636c-afc9-46ef-a733-9390babd2b8f","sequenceId":634},{"id":635,"end":2870.86,"note":"","text":"(鹿谷) ふむ…","start":2869.99,"favorite":false,"stableId":"a061955b-4e17-4d7a-87d0-798035a55fbb","sequenceId":635},{"id":636,"end":2873.32,"note":"","text":"(鹿谷) 順に挙げてこうか","start":2870.91,"favorite":false,"stableId":"5c4c211a-c978-4ae3-924a-fcec13dc8d3e","sequenceId":636},{"id":637,"end":2876.91,"note":"","text":"まず 古峨倫典の娘 古峨永遠","start":2873.37,"favorite":false,"stableId":"ac1aafc3-6262-41bb-a0ee-59070d85bdfd","sequenceId":637},{"id":638,"end":2878.62,"note":"","text":"(鹿谷)“永遠”と書いて“とわ”","start":2876.96,"favorite":false,"stableId":"48f75529-e74c-461e-b762-91dcc4ea5c30","sequenceId":638},{"id":639,"end":2882.51,"note":"","text":"亡霊になって現れるといわれてる 問題の少女だね","start":2878.67,"favorite":false,"stableId":"8633e6c6-7e94-4481-b401-517669d524a5","sequenceId":639},{"id":640,"end":2886.25,"note":"","text":"10年前 1979年８月","start":2882.66,"favorite":false,"stableId":"50346f4b-490e-42e3-a84b-bbafe5f7d66b","sequenceId":640},{"id":641,"end":2888.5,"note":"","text":"14歳の若さで死んだ","start":2886.3,"favorite":false,"stableId":"1dc38b28-791d-472f-8935-b6827f53cdec","sequenceId":641},{"id":642,"end":2890.48,"note":"","text":"これは病死とされている","start":2888.55,"favorite":false,"stableId":"8baceebd-d099-4a96-a347-6022d66f3041","sequenceId":642},{"id":643,"end":2893.59,"note":"","text":"次が 当時 古峨家の住み込みの――","start":2891.21,"favorite":false,"stableId":"6a16130b-4f72-4fd8-b55a-691cbf2b83b9","sequenceId":643},{"id":644,"end":2896.59,"note":"","text":"看護婦だった寺井明江という女性","start":2893.64,"favorite":false,"stableId":"03a52aa9-28b1-4884-8b95-bbecbde7f5b0","sequenceId":644},{"id":645,"end":2901.02,"note":"","text":"永遠が死んだ少しあとに 森の中で首をくくって自殺している","start":2896.64,"favorite":false,"stableId":"1105593f-37bc-4be8-88ff-9c9f1895450a","sequenceId":645},{"id":646,"end":2903.03,"note":"","text":"27歳だった","start":2901.07,"favorite":false,"stableId":"9040043d-b6fb-4c79-83f2-307c65586afb","sequenceId":646},{"id":647,"end":2907.15,"note":"","text":"(鹿谷) それから 昨日 玄関に出てきた女性","start":2903.34,"favorite":false,"stableId":"e131949e-97a9-4525-9976-4bcb4958b8d1","sequenceId":647},{"id":648,"end":2908.94,"note":"","text":"伊波紗世子さん","start":2907.2,"favorite":false,"stableId":"8973a1e1-11eb-457a-ab9f-6a2f4aa8f7fe","sequenceId":648},{"id":649,"end":2911.9,"note":"","text":"(福西) ああ… あの屋敷を管理してる人ですよね","start":2908.99,"favorite":false,"stableId":"29f70b9c-dc07-4f7e-b39a-61db61ab8255","sequenceId":649},{"id":650,"end":2913.49,"note":"","text":"うん　現在は そうだけど――","start":2911.95,"favorite":false,"stableId":"18580e73-5b33-4015-b3ce-4343e6a068e0","sequenceId":650},{"id":651,"end":2916.32,"note":"","text":"彼女には 裕作という夫がいて――","start":2913.54,"favorite":false,"stableId":"1e5284c9-cf2f-4d8a-a43c-b62071986b42","sequenceId":651},{"id":652,"end":2917.95,' WHERE "id" = '9ca51cd4-28eb-4034-ac60-51fd60f0f625' AND changes() = 1;

UPDATE "materials" SET "content_payload" = "content_payload" || '"note":"","text":"死んだ寺井明江と同じく――","start":2916.37,"favorite":false,"stableId":"15f7a3be-9d8a-4ee8-8ddc-fa7472a7c72e","sequenceId":652},{"id":653,"end":2922.26,"note":"","text":"もともとは 夫婦で古峨家に 住み込みで勤めていたらしい","start":2918,"favorite":false,"stableId":"801490ad-f612-4818-bbcf-8bb53eadb16a","sequenceId":653},{"id":654,"end":2925.67,"note":"","text":"２人の間には 今日子という娘がいて――","start":2922.36,"favorite":false,"stableId":"fc330c20-3530-4ed4-ba85-3f8c22ac944f","sequenceId":654},{"id":655,"end":2929.34,"note":"","text":"その子が 同じ８月に９歳で死んだ","start":2925.72,"favorite":false,"stableId":"a207adde-3a3a-4ff4-b82b-e65f09c7d88d","sequenceId":655},{"id":656,"end":2931.6,"note":"","text":"これも病死となっている","start":2929.39,"favorite":false,"stableId":"78b7d90f-2254-4b40-9cd3-e45b3ca66d09","sequenceId":656},{"id":657,"end":2937.3,"note":"","text":"…で 今度は その１か月後 父親の裕作が死んだ","start":2932.54,"favorite":false,"stableId":"51bb8cd4-101a-4f42-8ee8-c460bc3083bc","sequenceId":657},{"id":658,"end":2939.86,"note":"","text":"40歳 事故死だった","start":2937.35,"favorite":false,"stableId":"1b6e3585-4c4a-4d1f-9f72-5a61766c95e9","sequenceId":658},{"id":659,"end":2944.1,"note":"","text":"…で ５人目は 誰あろう古峨倫典","start":2940.09,"favorite":false,"stableId":"34fef506-4705-4596-a7ad-80bf63a25db2","sequenceId":659},{"id":660,"end":2946.31,"note":"","text":"翌80年の９月","start":2944.15,"favorite":false,"stableId":"8c68e0b8-535c-4cf3-a645-d1aca932b671","sequenceId":660},{"id":661,"end":2949.66,"note":"","text":"63歳 病死だった","start":2946.36,"favorite":false,"stableId":"76191ee7-538b-4d72-9e90-c5d286f4fca7","sequenceId":661},{"id":662,"end":2954.11,"note":"","text":"娘の永遠が死んだあと 屋敷の増築を始めて――","start":2950.85,"favorite":false,"stableId":"02f4e573-a351-4166-944b-bb312a7a3e33","sequenceId":662},{"id":663,"end":2957.67,"note":"","text":"それが完成した直後のこと だったという","start":2954.16,"favorite":false,"stableId":"d2e1ce0b-bc21-4515-b349-3ad176983b96","sequenceId":663},{"id":664,"end":2959.87,"note":"","text":"…で あと２人","start":2958.36,"favorite":false,"stableId":"f7f1c233-6226-4d0d-94bf-2b6083d3a7b0","sequenceId":664},{"id":665,"end":2963.75,"note":"","text":"１人は 古峨家の主治医だった 長谷川俊政","start":2959.92,"favorite":false,"stableId":"8f9ce737-d12a-42b9-bca8-6b8e2b1f07af","sequenceId":665},{"id":666,"end":2968.04,"note":"","text":"翌81年の12月 52歳で死んでいる","start":2963.8,"favorite":false,"stableId":"339606e0-c724-4ef7-be4c-c097e1a6b47b","sequenceId":666},{"id":667,"end":2972.77,"note":"","text":"開業していた医院が火事になって そのときに","start":2968.09,"favorite":false,"stableId":"b0628ccd-9ecf-494d-987d-2a1f2cb8545d","sequenceId":667},{"id":668,"end":2975.67,"note":"","text":"(鹿谷) 最後の１人は 服部郁夫といって――","start":2973.25,"favorite":false,"stableId":"ae041c04-ecab-4d32-9772-447c2788811e","sequenceId":668},{"id":669,"end":2977.3,"note":"","text":"倫典が引退したあと――","start":2975.72,"favorite":false,"stableId":"4ed1eb56-153d-4ad3-b6b3-da7ec2e1827d","sequenceId":669},{"id":670,"end":2980.43,"note":"","text":"古峨精計社の 専務に納まっていた男だ","start":2977.35,"favorite":false,"stableId":"0a4cb76f-3382-4807-b5e5-b946e12207f5","sequenceId":670},{"id":671,"end":2984.1,"note":"","text":"倫典には 随分と かわいがられていたらしいんだが――","start":2980.48,"favorite":false,"stableId":"e078976e-c779-4466-b244-c516b0044499","sequenceId":671},{"id":672,"end":2988.29,"note":"","text":"82年の３月 45歳で死んだ","start":2984.15,"favorite":false,"stableId":"e73030d7-fa5d-48a7-a4ea-04ce9b95515a","sequenceId":672},{"id":673,"end":2991.16,"note":"","text":"これも交通事故だった","start":2988.39,"favorite":false,"stableId":"628b575d-562b-4f51-a101-67a16b108419","sequenceId":673},{"id":674,"end":2994.46,"note":"","text":"異常だと思わないかい？","start":2991.51,"favorite":false,"stableId":"20c3ed07-c9e4-48be-b917-fa73f78cf5c4","sequenceId":674},{"id":675,"end":2999.01,"note":"","text":"まるで 連鎖反応みたいにして これだけの人間が死んでるんだ","start":2994.52,"favorite":false,"stableId":"586bec82-2169-4e83-a5ad-54fa5b846631","sequenceId":675},{"id":676,"end":3004.39,"note":"","text":"何かがあるような気が 僕にはするんだがねえ","start":2999.4,"favorite":false,"stableId":"95c48d7b-28d3-4f37-9dca-32e1a0a28063","sequenceId":676},{"id":677,"end":3015.65,"note":"","text":"(テレビの音楽)","start":3012.91,"favorite":false,"stableId":"2df42d78-4c43-41a8-a94f-52f4716d20fa","sequenceId":677},{"id":678,"end":3018.11,"note":"","text":"(福西) 鹿谷さん","start":3016.41,"favorite":false,"stableId":"944c52b9-aa6e-4d9f-b8d5-8db11b57d68b","sequenceId":678},{"id":679,"end":3019.63,"note":"","text":"(鹿谷) うん？","start":3018.46,"favorite":false,"stableId":"e30e3200-413b-4adb-9872-8784bc4520ea","sequenceId":679},{"id":680,"end":3024.11,"note":"","text":"最初に死んだ その永遠って娘ですけど――","start":3019.68,"favorite":false,"stableId":"eeecf05e-6aac-465b-9313-6120f02f52c7","sequenceId":680},{"id":681,"end":3028.7,"note":"","text":"実は 僕 会ったことが あるかもしれないんです","start":3025.17,"favorite":false,"stableId":"00f23145-d538-4801-b9dd-bbf42811023d","sequenceId":681},{"id":682,"end":3030.45,"note":"","text":"えっ？","start":3028.93,"favorite":false,"stableId":"35992604-a58b-4b9e-816a-01c53463cfa1","sequenceId":682},{"id":683,"end":3032.41,"note":"","text":"いつのことなんだい？ それは","start":3030.5,"favorite":false,"stableId":"b94046b2-9647-4ea0-8998-b64982ce18bf","sequenceId":683},{"id":684,"end":3038.17,"note":"","text":"10年前 小学校５年の夏休みです","start":3033.6,"favorite":false,"stableId":"332870ca-2d8c-45a2-9f83-5fc23407e93f","sequenceId":684},{"id":685,"end":3044.49,"note":"","text":"今 時計館にいる瓜生と河原崎 あと 樫と僕の４人で――","start":3038.56,"favorite":false,"stableId":"5f0cb467-6660-4cc6-b463-1f043586268b","sequenceId":685},{"id":686,"end":3049.51,"note":"","text":"塾の合宿を抜け出して 森の中へ遊びに行ったとき","start":3044.54,"favorite":false,"stableId":"537bd06b-af3e-4ded-9c06-20c395959a1b","sequenceId":686},{"id":687,"end":3052.85,"note":"","text":"(福西) とても きれいな女の子で","start":3050.41,"favorite":false,"stableId":"008c3cac-bb15-4bf2-96f0-1a94ded12a3e","sequenceId":687},{"id":688,"end":3054.59,"note":"","text":"僕たちよりも――","start":3053.28,"favorite":false,"stableId":"2fd103ba-4de8-4d0c-baf4-1ccd2a516d76","sequenceId":688},{"id":689,"end":3058.23,"note":"","text":"いくつか年上らしいということは 分かりました","start":3054.64,"favorite":false,"stableId":"48e9a750-7fd1-4f06-9ba1-ca850c3930c5","sequenceId":689},{"id":690,"end":3062.74,"note":"","text":"その子は あの屋敷に住んでたみたいで――","start":3059.37,"favorite":false,"stableId":"97317f91-4359-4871-972e-428051d92539","sequenceId":690},{"id":691,"end":3066.14,"note":"","text":"どういう状況かは 思い出せないけど――","start":3062.79,"favorite":false,"stableId":"e9cfd7a5-7c84-427f-8422-d25df89b17fe","sequenceId":691},{"id":692,"end":3069.27,"note":"","text":"なぜか送っていくことになって","start":3066.19,"favorite":false,"stableId":"45672fc8-6cbe-4ee1-a38f-4b6a23d8fa1b","sequenceId":692},{"id":693,"end":3070.64,"note":"","text":"(古峨永遠) アアーッ！","start":3069.32,"favorite":false,"stableId":"7a78686a-4340-4968-9dc7-024be86a5f99","sequenceId":693},{"id":694,"end":3072.06,"note":"","text":"ハッ!?","start":3070.69,"favorite":false,"stableId":"b43cda05-0cc8-445f-8cd1-c5c14097f24f","sequenceId":694},{"id":695,"end":3074.86,"note":"","text":"ハァハァ…","start":3072.11,"favorite":false,"stableId":"189d3caf-22cb-4fad-b4b4-5dfda8c70e60","sequenceId":695},{"id":696,"end":3078.21,"note":"","text":"(鹿谷) 正確に 何月何日のことか覚えてるかい？","start":3074.91,"favorite":false,"stableId":"7d9dd2e4-7bb1-4f3e-8e64-4cae16a33790","sequenceId":696},{"id":697,"end":3082.61,"note":"","text":"７月の後半だったことは 確かなんですけど――","start":3078.89,"favorite":false,"stableId":"24f9e49e-6784-4338-92fd-52092f1fe27e","sequenceId":697},{"id":698,"end":3084.47,"note":"","text":"日付までは…","start":3082.66,"favorite":false,"stableId":"e7995e02-651f-4556-a56b-8843237f2750","sequenceId":698},{"id":699,"end":3086.43,"note":"","text":"(鹿谷) いやぁ 面白い","start":3084.77,"favorite":false,"stableId":"f284beca-adb3-4554-88a9-a6ad3482ef95","sequenceId":699},{"id":700,"end":3090.25,"note":"","text":"10年前に 時計館の娘と出会った４人が――","start":3086.73,"favorite":false,"stableId":"86905ab5-0aa7-499a-8c84-3bed6c7ab90b","sequenceId":700},{"id":701,"end":3096.77,"note":"","text":"10年後の今 そろって また 時計館を訪れる運びになったわけか","start":3090.3,"favorite":false,"stableId":"bf8a3bed-e32d-4b30-9a99-759be81d234c","sequenceId":701},{"id":702,"end":3099.67,"note":"","text":"こいつは いよいよ…","start":3097.33,"favorite":false,"stableId":"52ae2863-c007-4c42-a46a-aa56f1764181","sequenceId":702},{"id":703,"end":3101.42,"note":"","text":"何かあるっていうんですか？","start":3099.72,"favorite":false,"stableId":"a31059bb-5666-471b-82d5-c59343e2ac7e","sequenceId":703},{"id":704,"end":3102.98,"note":"","text":"うん？","start":3101.47,"favorite":false,"stableId":"c165d21c-6b17-4e65-946b-373c73a3e69f","sequenceId":704},{"id":705,"end":3107.49,"note":"","text":"いや ここで臆測を巡らすのは 控えておこう","start":3103.71,"favorite":false,"stableId":"1545f2a3-de92-4acc-938f-ebbfa4c34a85","sequenceId":705},{"id":706,"end":3110.81,"note":"","text":"ただひとつ 僕にはね","start":3108.63,"favorite":false,"stableId":"dfce3843-321d-4af7-a604-e99eac16b5a1","sequenceId":706},{"id":707,"end":3114.29,"note":"","text":"どうも 気になることがあるんだが…","start":3110.86,"favorite":false,"stableId":"5ace4354-1c7e-4b2b-848c-d832dec61b6f","sequenceId":707},{"id":708,"end":3116.02,"note":"","text":"何ですか？","start":3114.39,"favorite":false,"stableId":"6e184e0c-7222-433e-9d99-66186dbf6b11","sequenceId":708},{"id":709,"end":3119.73,"note":"","text":"(鹿谷) ７人の死者の２番目 看護婦の寺井明江には――","start":3116.07,"favorite":false,"stableId":"77f14123-7ec0-4bb9-8025-ae7f7b33c831","sequenceId":709},{"id":710,"end":3122.53,"note":"","text":"光江という名前の 妹がいたはずなんだが…","start":3119.78,"favorite":false,"stableId":"cf637e74-4ff9-42dc-b890-a51aa2cfd33a","sequenceId":710},{"id":711,"end":3124.11,"note":"","text":"(電話のベル)","start":3122.58,"favorite":false,"stableId":"a5937640-8edc-4958-943a-b1a9176f6b12","sequenceId":711},{"id":712,"end":3125.24,"note":"","text":"失礼","start":3124.16,"favorite":false,"stableId":"cf8de572-2575-4a0b-b674-822df101d351","sequenceId":712},{"id":713,"end":3127.99,"note":"","text":"(電話のベル)","start":3125.29,"favorite":false,"stableId":"162e7e31-d4d6-4b3e-97c5-30e43e7f8d50","sequenceId":713},{"id":714,"end":3129.33,"note":"","text":"(鹿谷) はい 鹿谷です","start":3128.04,"favorite":false,"stableId":"986faf94-53de-49c6-bc0f-cb9c48f0218e","sequenceId":714},{"id":715,"end":3131.6,"note":"","text":"(伊波) 夜分遅くに… (福西) こんな時間に…","start":3129.38,"favorite":false,"stableId":"e50e1c68-c149-4373-bfc5-1959ceccad3d","sequenceId":715},{"id":716,"end":3133.46,"note":"","text":"(伊波) 伊波と申します","start":3131.95,"favorite":false,"stableId":"30a43c16-43d8-414a-a6d9-538565168fa8","sequenceId":716},{"id":717,"end":3136.75,"note":"","text":"(鹿谷) あ～ ゆうべは 大変 失礼しました","start":3133.51,"favorite":false,"stableId":"dabe5ada-2d13-4380-bb0e-c607303086fe","sequenceId":717},{"id":718,"end":3138.34,"note":"","text":"(伊波) とんでもございません","start":3136.8,"favorite":false,"stableId":"7c2c502a-5532-4dab-8783-e9ff5581117b","sequenceId":718},{"id":719,"end":3142.51,"note":"","text":"鹿谷さまのご著作｢迷路館の殺人｣","start":3138.39,"favorite":false,"stableId":"aff0ad08-36fb-42d4-9712-8edc537bd5ab","sequenceId":719},{"id":720,"end":3144.47,"note":"","text":"とても面白く拝読しました","start":3142.56,"favorite":false,"stableId":"86597800-668a-4f03-b5b5-df4f9de528b8","sequenceId":720},{"id":721,"end":3146.01,"note":"","text":"誠に…","start":3144.52,"favorite":false,"stableId":"efb5bade-c537-4fbc-853a-071cc1444bef","sequenceId":721},{"id":722,"end":3149.16,"note":"","text":"(鹿谷) ハハッ… それはどうも 恐縮です","start":3146.06,"favorite":false,"stableId":"9036411b-e2f9-493d-b8e3-6389b3f0a545","sequenceId":722},{"id":723,"end":3151.82,"note":"","text":"はい","start":3150.3,"favorite":false,"stableId":"59307695-9502-4176-bc82-627ebb7af5f6","sequenceId":723},{"id":724,"end":3160.19,"note":"","text":"ええ　かまいませんよ","start":3158.68,"favorite":false,"stableId":"0c58425c-6201-4533-8bec-897668e07f33","sequenceId":724},{"id":725,"end":3163.13,"note":"","text":"いえ むしろ “喜んで”と言いたいくらいです","start":3160.24,"favorite":false,"stableId":"2b557275-b1a4-44cb-af25-15e686bf3edd","sequenceId":725},{"id":726,"end":3165.09,"note":"","text":"(受話器を置く音)","start":3163.52,"favorite":false,"stableId":"c5801302-4395-480b-ac03-3a7ac07db11d","sequenceId":726},{"id":727,"end":3169.87,"note":"","text":"今の電話 ひょっとして…","start":3167.52,"favorite":false,"stableId":"60838bc5-5884-41ff-8f80-5fe2a244076b","sequenceId":727},{"id":728,"end":3172.6,"note":"","text":"うん　伊波さんからだった","start":3169.92,"favorite":false,"stableId":"a94598cd-6ae2-4e7d-86d4-16fc8e057a76","sequenceId":728},{"id":729,"end":3185.07,"note":"","text":"(時鐘音)","start":3179.16,"favorite":false,"stableId":"0f507161-002f-4c60-a44c-2eb78cefa621","sequenceId":729},{"id":730,"end":3188.07,"note":"","text":"(江南) ンッ…","start":3186.58,"favorite":false,"stableId":"160f21d0-cdf5-4cdb-a295-79cad50ec8a6","sequenceId":730},{"id":731,"end":3190.57,"note":"","text":"(ため息)","start":3188.92,"favorite":false,"stableId":"e94e1a45-5891-44a0-b395-f5d4c4bd8f75","sequenceId":731},{"id":732,"end":3195.18,"note":"","text":"２時って…","start":3193.09,"favorite":false,"stableId":"3966c7b5-a2d9-444a-a5f9-3909a34572b2","sequenceId":732},{"id":733,"end":3197.24,"note":"","text":"もう午後？","start":3195.23,"favorite":false,"stableId":"9d58ed56-5451-4e8d-9ea1-fb3c6beb12b3","sequenceId":733},{"id":734,"end":3199.33,"note":"","text":"よいしょ","start":3197.55,"favorite":false,"stableId":"2bac37fc-ac02-42a9-ae89-075f74fea3de","sequenceId":734},{"id":735,"end":3208.88,"note":"","text":"(ドアの閉まる音)","start":3207.02,"favorite":false,"stableId":"7be8110a-a04c-4bf8-bf8e-8ea4fd3e3ae9","sequenceId":735},{"id":736,"end":3218.52,"note":"","text":"(江南) 何時間 寝たんだよ","start":3215.28,"favorite":false,"stableId":"4375c8be-5c41-4dfc-ad61-8f2db8dbad34","sequenceId":736},{"id":737,"end":3228.84,"note":"","text":"(江南) おはようございます","start":3227,"favorite":false,"stableId":"6fbd689b-7ecd-47d7-9c94-c60975498c57","sequenceId":737},{"id":738,"end":3230.09,"note":"","text":"(シャッター音)","start":3228.89,"favorite":false,"stableId":"d934d852-d0e6-4a31-98fd-421fdb5c523f","sequenceId":738},{"id":739,"end":3233.56,"note":"","text":"(内海) 午後２時 江南氏 起床と…","start":3230.14,"favorite":false,"stableId":"cd22880a-c508-478b-b718-f32087016dab","sequenceId":739},{"id":740,"end":3235.06,"note":"","text":"(シャッター音)","start":3233.61,"favorite":false,"stableId":"eef2339c-7d35-4ae9-987d-4a0f9e40ec6c","sequenceId":740},{"id":741,"end":3238.23,"note":"","text":"僕らも ちょっと前に 起きたばかりなんですよ","start":3235.11,"favorite":false,"stableId":"e1fd48a3-2d2a-4979-8c01-44c12bf75077","sequenceId":741},{"id":742,"end":3239.6,"note":"","text":"(内海) ムリもないよ","start":3238.28,"favorite":false,"stableId":"52571196-ae75-4259-adb6-035e45d8740b","sequenceId":742},{"id":743,"end":3243.42,"note":"","text":"時計の音が耳について よく寝つけないし","start":3239.65,"favorite":false,"stableId":"2c27a239-a8b6-4955-9a97-d8ba32d32d04","sequenceId":743},{"id":744,"end":3244.9,"note":"","text":"アア…","start":3243.77,"favorite":false,"stableId":"b79fdea1-5d6e-4f4b-a7c1-349476f27d2c","sequenceId":744},{"id":745,"end":3246.49,"note":"","text":"(渡辺) 頭 痛いんですか？","start":3244.95,"favorite":false,"stableId":"61b33591-2b5b-4d71-bd9f-070d58e70774","sequenceId":745},{"id":746,"end":3247.99,"note":"","text":"(内海) うん　ちょっとね","start":3246.54,"favorite":false,"stableId":"17c5f723-549f-473a-9286-9a120c072b29","sequenceId":746},{"id":747,"end":3250.71,"note":"","text":"きっと この家のせいだ","start":3248.04,"favorite":false,"stableId":"9d0dd2e3-c93e-40fa-b6e1-6a0e502a33b2","sequenceId":747},{"id":748,"end":3254.45,"note":"","text":"何ていうか 空気が変なんだな","start":3250.76,"favorite":false,"stableId":"572cddcd-5ac1-41c6-9afc-228956bf4ba3","sequenceId":748},{"id":749,"end":3256.08,"note":"","text":"よどんで透明じゃない","start":3254.5,"favorite":false,"stableId":"b223abcc-fa28-4ebd-a627-a1ce069c70a4","sequenceId":749},{"id":750,"end":3257.87,"note":"","text":"そんな感じがするんだよな","start":3256.13,"favorite":false,"stableId":"38885860-93aa-4dea-aff5-ac3d9c379213","sequenceId":750},{"id":751,"end":3261.25,"note":"","text":"(河原崎) まったく 古峨倫典って人","start":3257.92,"favorite":false,"stableId":"91655675-b8ef-41fe-970b-1286b83d56ad","sequenceId":751},{"id":752,"end":3264.94,"note":"","text":"なんだって こんな 妙ちくりんな家を建てたのかね","start":3261.3,"favorite":false,"stableId":"90e37e07-d1ff-4d61-bb06-4e0c1ace8076","sequenceId":752},{"id":753,"end":3267.59,"note":"","text":"(瓜生) コレクションを しまっておく以外にも――","start":3265.33,"favorite":false,"stableId":"b719ac7f-c336-4c0b-b921-ca678e5a9f7d","sequenceId":753},{"id":754,"end":3269.97,"note":"","text":"何か別の目的が あったのかもしれないな","start":3267.64,"favorite":false,"stableId":"70a4a0e2-1636-483b-8761-9b2943e44f6d","sequenceId":754},{"id":755,"end":3272.44,"note":"","text":"(こずえ) 別の目的って？","start":3270.02,"favorite":false,"stableId":"fa98e6c5-e01d-4294-a003-0ffb37e10893","sequenceId":755},{"id":756,"end":3274.51,"note":"","text":"(瓜生) 玄関のドア","start":3273,"favorite":false,"stableId":"530dc5a7-7580-4c50-8fa4-8330b98c1e0c","sequenceId":756},{"id":757,"end":3276.72,"note":"","text":"鉄製で しかも 内側からでも――","start":3274.56,"favorite":false,"stableId":"16fabdef-2fd6-4507-a64c-1f5ec2d980f6","sequenceId":757},{"id":758,"end":3279.54,"note":"","text":"鍵がないと 開けられないような仕組み","start":3276.77,"favorite":false,"stableId":"38d8d0a4-df11-49ab-b3ad-26b01e3c8d08","sequenceId":758},{"id":759,"end":3285.75,"note":"","text":"これって まるで 中に人を 閉じ込めるため …みたいじゃないか？","start":3280.01,"favorite":false,"stableId":"b72f881c-1e04-45af-8c05-a8b6efdc72d0","sequenceId":759},{"id":760,"end":3288.25,"note":"","text":"(小早川) おはよう","start":3286.64,"favorite":false,"stableId":"5714ad56-92dc-40c5-ad31-9f69937e5a44","sequenceId":760},{"id":761,"end":3291.03,"note":"","text":"(瓜生たち) おはようございます","start":3289.1,"favorite":false,"stableId":"a6c5312e-e8cc-4e11-8cd5-595275c788e5","sequenceId":761},{"id":762,"end":3293.09,"note":"","text":"さすがに みんな もう おそろいか","start":3291.08,"favorite":false,"stableId":"11cd16a3-818b-4ebc-a8e0-ddcad9dc6189","sequenceId":762},{"id":763,"end":3296.16,"note":"","text":"(内海) 光明寺さんは まだみたいですけど","start":3293.48,"favorite":false,"stableId":"f27caf12-3fd8-4d34-be46-0ce6f0def593","sequenceId":763},{"id":764,"end":3300.18,"note":"","text":"(早紀子) あ… あの 光明寺さん 部屋にいないんです","start":3296.21,"favorite":false,"stableId":"81c0a65a-d6f1-4cbf-916b-c1eb4b84843d","sequenceId":764},{"id":765,"end":3303.08,"note":"","text":"(河原崎) いないって 部屋の中を見たのか？","start":3300.49,"favorite":false,"stableId":"331f22dd-9dce-499b-9cb0-eb9f13d587be","sequenceId":765},{"id":766,"end":3306.38,"note":"","text":"(早紀子) うん ノックしても返事がないから","start":3303.13,"favorite":false,"stableId":"abbf6c45-53a1-4205-9cda-a82f12a9e4ef","sequenceId":766},{"id":767,"end":3308.52,"note":"","text":"鍵もかかってなくて","start":3306.43,"favorite":false,"stableId":"fe4ef2ec-a0bb-43c6-8547-76ead9bcb937","sequenceId":767},{"id":768,"end":3313.28,"note":"","text":"まさか…","start":3311.58,"favorite":false,"stableId":"c6c6560a-f193-4b40-9f04-4e623d0e49d7","sequenceId":768},{"id":769,"end":3316.32,"note":"","text":"(小早川)“まさか”って何だよ","start":3314.3,"favorite":false,"stableId":"96735542-3c00-4454-b0e4-9b0b474ae637","sequenceId":769},{"id":770,"end":3335.62,"note":"","text":"(江南) 交霊会のあと見つかった あの鍵","start":3333.56,"favorite":false,"stableId":"899d84f5-7541-4d23-bbd4-f86defc28b28","sequenceId":770},{"id":771,"end":3338.68,"note":"","text":"この扉の鍵だったんじゃ ないでしょうか","start":3335.67,"favorite":false,"stableId":"04659ed0-ae13-46d7-a0cb-dbba784a13c9","sequenceId":771},{"id":772,"end":3348.98,"note":"","text":"(ドアの開く音)","start":3345.45,"favorite":false,"stableId":"7199ad4d-6792-4d34-a674-5c83d2dac3ef","sequenceId":772},{"id":773,"end":3363.56,"note":"","text":"おかしいです","start":3362.01,"favorite":false,"stableId":"b6b536ce-7543-4abc-8857-d8f52bbf67f9","sequenceId":773},{"id":774,"end":3366.12,"note":"","text":"ゆうべは 明かりもついていたのに","start":3363.61,"favorite":false,"stableId":"d0ea2068-7784-4c1e-ab09-aad80fdfa3ad","sequenceId":774},{"id":775,"end":3373.17,"note":"","text":"(小早川) 何だ？ こいつは 一体…","start":3369.77,"favorite":false,"stableId":"7c5f5293-21dc-44a8-be78-cda4dfce8f75","sequenceId":775},{"id":776,"end":3382.96,"note":"","text":"(江南) ３時45分…","start":3380.15,"favorite":false,"stableId":"06359c0e-0aba-4075-a142-a6e397300c36","sequenceId":776},{"id":777,"end":3386.13,"note":"","text":"僕が部屋の外にいたのは３時半","start":3383.01,"favorite":false,"stableId":"b31b633c-a5a7-47f9-8593-bff9407539da","sequenceId":777},{"id":778,"end":3388.71,"note":"","text":"(小早川) どうやら お前が立ち去ったあとで――","start":3386.18,"favorite":false,"stableId":"0a21bc20-8199-4e46-9b65-9fda2bc33a73","sequenceId":778},{"id":779,"end":3390.46,"note":"","text":"壊されたようだな","start":3388.76,"favorite":false,"stableId":"f368f376-1594-4f56-b28d-435214c943ee","sequenceId":779},{"id":780,"end":3393.61,"note":"","text":"誰が どうして こんな ひどいことを","start":3390.51,"favorite":false,"stableId":"e1fade4b-650f-4f56-aefb-ab25d2120b37","sequenceId":780},{"id":781,"end":3396.74,"note":"","text":"(小早川) 分からん","start":3395.25,"favorite":false,"stableId":"9b' WHERE "id" = '9ca51cd4-28eb-4034-ac60-51fd60f0f625' AND changes() = 1;

UPDATE "materials" SET "content_payload" = "content_payload" || '1eaad4-523d-4991-ae3c-5a09eb1c920f","sequenceId":781},{"id":782,"end":3403.03,"note":"","text":"とにかく 光明寺さんを捜さないと","start":3398.71,"favorite":false,"stableId":"0f3b2cf5-7b97-473b-ae02-df9ec6433918","sequenceId":782},{"id":783,"end":3407.77,"note":"","text":"お前は奥を調べてくれ","start":3404.97,"favorite":false,"stableId":"35897e51-31e3-4710-ace2-356137644f16","sequenceId":783},{"id":784,"end":3409,"note":"","text":"(江南) はい","start":3407.82,"favorite":false,"stableId":"e31c9d15-b8c7-4e52-8481-97e9e83a8acb","sequenceId":784},{"id":785,"end":3411,"note":"","text":"(ドアの開く音)","start":3409.14,"favorite":false,"stableId":"553dfb20-886e-4a66-b900-413414a09686","sequenceId":785},{"id":786,"end":3417.97,"note":"","text":"(明かりのつく音)","start":3416.36,"favorite":false,"stableId":"03ef5d60-9d72-4f41-8640-356358661195","sequenceId":786},{"id":787,"end":3425.39,"note":"","text":"(江南) ここも","start":3423.99,"favorite":false,"stableId":"ba765a3a-97e2-479d-99d2-42f639c6b2e9","sequenceId":787},{"id":788,"end":3440.26,"note":"","text":"(小早川) おい 江南","start":3437.79,"favorite":false,"stableId":"d866266d-3092-46ea-a9b2-2ddb3b1a9573","sequenceId":788},{"id":789,"end":3441.7,"note":"","text":"(江南) はい","start":3440.31,"favorite":false,"stableId":"3345977a-8fa3-4787-8ded-3321f53caa5c","sequenceId":789},{"id":790,"end":3447.58,"note":"","text":"(小早川) そいつを見てくれないか？","start":3445.47,"favorite":false,"stableId":"192a1124-c5d6-4fcc-8aff-f187a3044986","sequenceId":790},{"id":791,"end":3460.74,"note":"","text":"(小早川) 血の跡のように見えないか？","start":3458.4,"favorite":false,"stableId":"c0b52538-256e-4948-94ef-2f56c574dc68","sequenceId":791},{"id":792,"end":3463.51,"note":"","text":"しかも そんなに古くない","start":3460.79,"favorite":false,"stableId":"1c32bf33-f761-4326-a10a-94dcc3de623a","sequenceId":792},{"id":793,"end":3470.35,"note":"","text":"まさか 光明寺さんは この場所で 誰かに襲われて…","start":3464.11,"favorite":false,"stableId":"2df8778c-11cc-4058-8ca8-2f86e89d07d5","sequenceId":793},{"id":794,"end":3479.07,"note":"","text":"この時計は ３時半少し前で止まっています","start":3474.04,"favorite":false,"stableId":"e5a58c7c-e7fd-4217-bf8f-a78830175951","sequenceId":794},{"id":795,"end":3484.03,"note":"","text":"僕が あの音を聞いた時刻と ちょうど合います","start":3480.21,"favorite":false,"stableId":"ca0ee059-52e5-4526-a4f9-90b8964f1756","sequenceId":795},{"id":796,"end":3492.12,"note":"","text":"(小早川) 仮に そうだとしてもだ","start":3489.8,"favorite":false,"stableId":"0f540176-1e1d-473c-a0bf-acf494de4e48","sequenceId":796},{"id":797,"end":3498.24,"note":"","text":"彼女は 一体 どこに 消えちまったっていうんだよ!?","start":3494.23,"favorite":false,"stableId":"17adb52a-4069-43e9-8065-c854f45361cf","sequenceId":797},{"id":798,"end":3500.17,"note":"","text":"(江南) それは…","start":3498.29,"favorite":false,"stableId":"73050c48-222d-43a3-aec1-ae38084e885c","sequenceId":798},{"id":799,"end":3503.87,"note":"","text":"あの扉","start":3502.4,"favorite":false,"stableId":"00455e73-dab1-4914-b3d0-6a84dcfc7469","sequenceId":799},{"id":800,"end":3505.29,"note":"","text":"(小早川) えっ？","start":3503.92,"favorite":false,"stableId":"eb9b2ab3-3490-447f-ab87-6c589bf4f44e","sequenceId":800},{"id":801,"end":3507.6,"note":"","text":"(江南) クローゼットかもしれません","start":3505.34,"favorite":false,"stableId":"ccda4751-d020-4ad2-9f49-3b0b3d62fb14","sequenceId":801},{"id":802,"end":3527.37,"note":"","text":"(明かりのつく音)","start":3525.92,"favorite":false,"stableId":"8cc66ef6-e52c-4239-b960-3949981f8b82","sequenceId":802},{"id":803,"end":3547.87,"note":"","text":"ウワッ…","start":3546.53,"favorite":false,"stableId":"1d4204b1-dafa-4c4c-80c0-102425d7a449","sequenceId":803},{"id":804,"end":3549.43,"note":"","text":"どうした？","start":3547.92,"favorite":false,"stableId":"39f13435-752d-4cc8-a883-86b0b1912a29","sequenceId":804},{"id":805,"end":3551.47,"note":"","text":"(江南) いえ…","start":3549.91,"favorite":false,"stableId":"9a462140-6932-4273-bf36-fecee5b052c8","sequenceId":805},{"id":806,"end":3579.03,"note":"","text":"(江南) ハァハァハァ…","start":3572.97,"favorite":false,"stableId":"a8398d71-0cd3-48ef-85d6-b4f586e6c8e9","sequenceId":806},{"id":807,"end":3582.4,"note":"","text":"ハァハァ…","start":3579.08,"favorite":false,"stableId":"e9ea2941-0d0f-4936-984f-bc8ffe39e5f0","sequenceId":807},{"id":808,"end":3583.92,"note":"","text":"あっ…","start":3582.45,"favorite":false,"stableId":"2064fcc1-e2e6-47f8-b118-5e2c85d63f6d","sequenceId":808},{"id":809,"end":3587.41,"note":"","text":"(瓜生) どうして そのとき 誰かに すぐ知らせなかったんですか？","start":3584.98,"favorite":false,"stableId":"88e5cfe3-7c0f-4a3f-b85a-85752975564e","sequenceId":809},{"id":810,"end":3588.91,"note":"","text":"(河原崎) 殺す理由なんてあるはずがない","start":3587.46,"favorite":false,"stableId":"c66ba7c4-d7d3-4fda-b778-bcf868539b29","sequenceId":810},{"id":811,"end":3590.45,"note":"","text":"(小早川) 私を疑ってんのか？","start":3588.96,"favorite":false,"stableId":"ea0229ee-dd89-4a48-bc97-1dba3b69e5b0","sequenceId":811},{"id":812,"end":3592.25,"note":"","text":"(渡辺) 警察に知らせたほうが いいんじゃないですか？","start":3590.5,"favorite":false,"stableId":"01d298d8-7bac-4d63-ac2b-beadbdf1a698","sequenceId":812},{"id":813,"end":3594.67,"note":"","text":"(伊波) この家は 不幸な家でございます","start":3592.3,"favorite":false,"stableId":"7164ef45-3397-41b6-96ee-ce7b98c36e26","sequenceId":813},{"id":814,"end":3596,"note":"","text":"(野之宮) 死神を見たんじゃ","start":3594.72,"favorite":false,"stableId":"39d847d4-391c-49df-92ad-5792d0d9af24","sequenceId":814},{"id":815,"end":3597.13,"note":"","text":"(福西) 何か考えが？","start":3596.05,"favorite":false,"stableId":"30a1e60f-c93b-46be-8e1e-f1f986cd682a","sequenceId":815},{"id":816,"end":3598.17,"note":"","text":"(鹿谷) うん？","start":3597.18,"favorite":false,"stableId":"506b0f31-1549-4e53-beab-ec46c9bc6229","sequenceId":816},{"id":817,"end":3600.31,"note":"","text":"さっぱりだね　フフッ…","start":3598.22,"favorite":false,"stableId":"3724ac1e-b9e3-417e-88d8-188dca81fb83","sequenceId":817}],"subtitleSeason":"1","subtitleEpisode":"1","subtitleNoAudio":true,"subtitleWorkTitle":"钟表馆事件","subtitleSourceType":"TV"}' WHERE "id" = '9ca51cd4-28eb-4034-ac60-51fd60f0f625' AND changes() = 1;

INSERT OR IGNORE INTO "materials" ("id", "type", "title", "chapter_name", "content_payload", "metadata", "created_at", "updated_at") VALUES
('440ebb77-7b2d-4ff4-8ad4-5e7ceb80f8c5', 'SPEAKING', 'Section6', 'Section6', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit3/Unit03Section06.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit3/Unit03Section06.mp3","dialogues":[{"id":836,"end":7.51,"text":"1、あーあ、あと半年で卒業。","start":2.17,"sequenceId":1},{"id":837,"end":9.56,"text":"4月から社会人だよ。","start":7.56,"sequenceId":2},{"id":838,"end":13.9,"text":"本当。だから今のうちにやりたいことやっておかなくちゃね。","start":9.71,"sequenceId":3},{"id":839,"end":18.63,"text":"2、あのー、すみません。","start":15.11,"sequenceId":4},{"id":840,"end":23.73,"text":"明日国に帰るので、バイト一週間休ませていただけませんか？","start":18.73,"sequenceId":5},{"id":841,"end":25.91,"text":"えっ、困るな。","start":23.91,"sequenceId":6},{"id":842,"end":28.14,"text":"もっと早く言ってくれないと…。","start":25.96,"sequenceId":7},{"id":843,"end":31.92,"text":"3、洋服は燃えるゴミ。","start":28.59,"sequenceId":8},{"id":844,"end":34.35,"text":"アルミホイルは燃えないゴミだよ。","start":32.01,"sequenceId":9},{"id":845,"end":38.44,"text":"あ〜、ゴミの分別は本当に複雑。","start":34.53,"sequenceId":10},{"id":846,"end":45.47,"text":"4、赤ワインは体にいいって言われてるから、たくさん飲んでも大丈夫！","start":39.43,"sequenceId":11},{"id":847,"end":48.69,"text":"そうかもしれないけど、飲みすぎはよくないんじゃない？","start":45.52,"sequenceId":12},{"id":848,"end":54.36,"text":"5、ずっと応援してるから、試合頑張ってね。","start":49.96,"sequenceId":13},{"id":849,"end":56.37,"text":"うん、ありがとう。","start":54.6,"sequenceId":14},{"id":850,"end":58.02,"text":"精一杯頑張るよ。","start":56.42,"sequenceId":15},{"id":851,"end":62.31,"text":"6、明日の飲み会、","start":58.95,"sequenceId":16},{"id":852,"end":65.14,"text":"行こうかな、やめようかな、","start":62.36,"sequenceId":17},{"id":853,"end":66.99,"text":"どうしようかな。","start":65.46,"sequenceId":18},{"id":854,"end":69.48,"text":"もう、行くって言ってあるんでしょ？","start":67.19,"sequenceId":19},{"id":855,"end":71.24,"text":"じゃー、行かなきゃ。","start":69.7,"sequenceId":20},{"id":856,"end":75.89,"text":"7、土日は働けますか？","start":72.34,"sequenceId":21},{"id":857,"end":79.08,"text":"すみません。土曜日はちょっと…。","start":76.13,"sequenceId":22},{"id":858,"end":81.64,"text":"でも日曜日なら大丈夫です。","start":79.46,"sequenceId":23},{"id":859,"end":85.08,"text":"8、グッチって何？","start":82.27,"sequenceId":24},{"id":860,"end":86.46,"text":"ブランドのこと。","start":85.44,"sequenceId":25},{"id":861,"end":88.69,"text":"知ってそうで、いがいと知らないんだね。","start":86.46,"sequenceId":26},{"id":862,"end":94.66,"text":"9、後で食べようと思ってたケーキ、食べたのだれ？","start":89.41,"sequenceId":27},{"id":863,"end":97.53,"text":"あ、ごめん。わざとじゃないよ。","start":94.71,"sequenceId":28},{"id":864,"end":101.07,"text":"10、ご注文は？","start":98.29,"sequenceId":29},{"id":865,"end":103.38,"text":"じゃー、とりあえずビール。","start":101.41,"sequenceId":30}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:11:01.768+00:00'),
('5e4ae333-91e6-44df-88c0-526bf016729e', 'SPEAKING', 'Section5', 'Section5', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit1/Unit01Section05.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit1/Unit01Section05.mp3","dialogues":[{"id":114,"end":5.61,"text":"1、何才ですか？","start":2.69,"sequenceId":1},{"id":115,"end":7.35,"text":"28才です。","start":5.8,"sequenceId":2},{"id":116,"end":10.83,"text":"2、どんな映画を見ますか？","start":7.99,"sequenceId":3},{"id":117,"end":12.92,"text":"コメディーをよく見ますね。","start":11.02,"sequenceId":4},{"id":118,"end":17.01,"text":"3、黄色と赤の花をください。","start":13.48,"sequenceId":5},{"id":119,"end":19.33,"text":"はい、黄色と赤ですね。","start":17.06,"sequenceId":6},{"id":120,"end":23.41,"text":"4、今日は暑いですね。","start":20.31,"sequenceId":7},{"id":121,"end":25.33,"text":"ええ、本当に。","start":23.59,"sequenceId":8},{"id":122,"end":29.67,"text":"5、日本語の勉強はどうですか？","start":25.96,"sequenceId":9},{"id":123,"end":33,"text":"漢字はむずかしいですが、とてもおもしろいです。","start":30,"sequenceId":10},{"id":124,"end":36.08,"text":"6、いくらですか？","start":33.37,"sequenceId":11},{"id":125,"end":37.65,"text":"210円です。","start":36.15,"sequenceId":12},{"id":126,"end":42.23,"text":"7、テスト、むずかしいですか？","start":38.45,"sequenceId":13},{"id":127,"end":44.26,"text":"いいえ、かんたんですよ。","start":42.28,"sequenceId":14},{"id":128,"end":48.54,"text":"8、鈴木さんはどんな人ですか？","start":44.95,"sequenceId":15},{"id":129,"end":50.35,"text":"親切な人ですよ。","start":48.71,"sequenceId":16},{"id":130,"end":54.96,"text":"9、このくつ、ちょっと大きいです。","start":51.12,"sequenceId":17},{"id":131,"end":57.4,"text":"じゃー、これはどうですか？","start":55.18,"sequenceId":18},{"id":132,"end":61.64,"text":"10、これ、きれいですね。","start":58.16,"sequenceId":19},{"id":133,"end":63.92,"text":"ええ、とてもきれいですね。","start":61.78,"sequenceId":20}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:32:50.671+00:00');

